import {polygon,area} from './geometry.js';
export function rackStats(state,id){const racks=state.racks.filter(r=>r.sectionId===id);let used=0,assigned=0,pallets=0;for(const r of racks){const t=state.rackTypes.find(t=>t.id===r.typeId);if(!t)continue;const a=t.length*t.width;used+=a;if(r.assigned)assigned+=a;pallets+=t.pallets;}const section=state.shapes.find(s=>s.id===id),total=section?area(polygon(section)):0;return {total,used,assigned,unassigned:used-assigned,reserved:section?.rackPlacement===false?total:0,free:section?.rackPlacement===false?0:Math.max(0,total-used),count:racks.length,assignedCount:racks.filter(r=>r.assigned).length,pallets};}
export function racksValid(s){return Array.isArray(s.shapes)&&s.shapes.every(o=>o&&typeof o.id==='string')&&Array.isArray(s.rackTypes)&&s.rackTypes.length<=100&&new Set(s.rackTypes.map(t=>t.id)).size===s.rackTypes.length&&s.rackTypes.every(t=>t&&typeof t.id==='string'&&typeof t.name==='string'&&t.name.length>0&&t.name.length<=100&&['length','width','height'].every(k=>Number.isFinite(t[k])&&t[k]>0&&t[k]<=1000)&&Number.isInteger(t.pallets)&&t.pallets>0&&t.pallets<=100000)&&Array.isArray(s.racks)&&s.racks.length<=2000&&new Set(s.racks.map(r=>r.id)).size===s.racks.length&&s.racks.every(r=>r&&typeof r.id==='string'&&typeof r.assigned==='boolean'&&s.rackTypes.some(t=>t.id===r.typeId)&&s.shapes.some(o=>o.id===r.sectionId&&o.layer==='section'&&o.rackPlacement!==false))&&s.shapes.filter(o=>o.layer==='section').every(o=>rackStats(s,o.id).used<=area(polygon(o))+1e-6);}
export function clip(poly,axis,value,less=true){const out=[];if(!poly.length)return out;for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],ai=less?a[axis]<=value:a[axis]>=value,bi=less?b[axis]<=value:b[axis]>=value;if(ai)out.push(a);if(ai!==bi){const t=(value-a[axis])/(b[axis]-a[axis]);out.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}}return out;}
export function areaCut(poly,axis,target,less=true){let lo=Math.min(...poly.map(p=>p[axis])),hi=Math.max(...poly.map(p=>p[axis]));for(let i=0;i<55;i++){const mid=(lo+hi)/2,a=area(clip(poly,axis,mid,less));if((a<target)===less)lo=mid;else hi=mid;}return (lo+hi)/2;}
export function allocation(section,stats){const p=polygon(section);if(stats.used<=0)return {rack:[],assigned:[]};const x=areaCut(p,'x',Math.min(stats.used,stats.total)),rack=clip(p,'x',x),y=areaCut(rack,'y',stats.assigned,false);return {rack,assigned:stats.assigned>0?clip(rack,'y',y,false):[],x,y};}
